<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="theme-color" content="#0d1424" />
    <meta
      name="description"
      content="Solmara Streets: a deterministic procedural coastal city you can walk, drive, fight and work five jobs in, rendered with three.js and no downloaded assets."
    />
    <title>Solmara Streets</title>
    <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='12' fill='%2310161f'/%3E%3Ccircle cx='42' cy='22' r='12' fill='%23ffb066'/%3E%3Crect x='8' y='40' width='48' height='4' fill='%237fb6d9'/%3E%3C/svg%3E" />
    <link rel="stylesheet" href="./styles/base.css" />
  </head>
  <body>
    <!-- The one canvas the whole game draws into. -->
    <canvas id="viewport" width="1280" height="720" aria-label="Solmara Streets, an open-world city"></canvas>

    <!-- Boot card: visible until the first frame of the city is on screen. -->
    <section id="boot" class="boot">
      <div class="boot-mark">SOLMARA</div>
      <h1 class="boot-title">Streets</h1>
      <p class="boot-line">A sun-soaked coastal city, three hundred days of summer.</p>
      <p class="boot-status" id="boot-status">Laying out the districts&hellip;</p>
      <p class="boot-keys">WASD walk · Shift sprint · Space jump · F steal a car · V camera · T skips an hour · Esc pause</p>
    </section>

    <!-- The HUD (district, speed, prompt) is built in here by src/hud/hud.js. -->
    <div id="hud-root" class="hud-root"></div>

    <!-- Frame time readout, toggled with F3. -->
    <pre id="perf" class="perf" hidden></pre>

    <!-- The one error surface: window errors and unhandled rejections land here. -->
    <div id="error-overlay" class="error-overlay" hidden>
      <div class="error-card">
        <h2 class="error-title">Solmara Streets hit a fault</h2>
        <p class="error-hint">This is the game, not your browser. The frame that broke is described below.</p>
        <pre class="error-body" id="error-body"></pre>
      </div>
    </div>

    <!-- Three.js is vendored beside the page: no build step and no network request.
         The deterministic shot rig is selected with ?shot=…, handled in src/shots/rig.js. -->
    <script src="./vendor/three.min.js"></script>
    <script type="module" src="./src/main.js"></script>
  </body>
</html>
