  { until: 17, id: 'afternoon', label: 'Afternoon' },
  { until: 19.2, id: 'golden', label: 'Golden hour' },
  { until: 20.8, id: 'dusk', label: 'Dusk' },
  { until: 24.1, id: 'night', label: 'Night' },
