    palette.sunDir = this._sun;
    palette.moonDir = this._moon.copy(this._sun).multiplyScalar(-1);
    palette.hour = this.hour;
    palette.phase = this.phase.id;
    palette.label = this.label;
    this._palette = palette;
    this._lastKey = key;
    return palette;
  }
