  for (let i = 0; i < points.length; i += 1) {
    const a = points[i];
    const b = points[(i + 1) % points.length];
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const length = Math.hypot(dx, dz);
    segments.push({
      index: i,
      ax: a.x,
      az: a.z,
      bx: b.x,
      bz: b.z,
      length,
      dirX: dx / length,
      dirZ: dz / length,
      y: HIGHWAY.height,
      width: HIGHWAY.width,
    });
  }
  return { points, segments, height: HIGHWAY.height, width: HIGHWAY.width };
