    blotch(ctx, random, width, height, 18, mixHex(wall, 0xffffff, 0.3), 0.1);
    speckle(ctx, random, width, height, 1600, [mixHex(wall, 0x000000, 0.2), mixHex(wall, 0xffffff, 0.2)], 0.18);

