        ctx.fillRect(x - 2, y + h, w + 4, 3);
        if (districtId === 'verano' && row % 3 === 1) {
          ctx.fillStyle = hex(palette.trim);
          ctx.fillRect(x - 3, y + h + 3, w + 6, 4);
